let currentPerson='Rosa',composeDraft=null;
const teamPeople=['Rosa','Carmen','Lucía'];
const nowText=()=>new Date().toLocaleString('es-PE',{timeZone:'America/Lima',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function teamDate(value){return new Date(value+'T12:00:00-05:00').toLocaleDateString('es-PE',{timeZone:'America/Lima',weekday:'long',day:'numeric',month:'long'})}
function initWorkScope(){
 state.supportRequests??=[];
 if(!state.workScopeVersion){
   for(const r of state.repairs){let person=r.responsible||r.receivedBy||'Rosa';for(const t of state.teamParcels||[]){const i=t.items.find(i=>i.repairId===r.id);if(i?.receipt==='received'&&!i.returned)person=t.to}if(r.returnTransfer?.stage==='received')person=r.returnTransfer.receivedBy||person;r.responsible=person;
     if(['out_wait','out_route','out_arrived'].includes(r.stage)){r.legacyLogisticsStage=r.stage;r.stage='pending'}
     if(['return_wait','return_pickup','return_route'].includes(r.stage)){r.legacyLogisticsStage=r.stage;r.stage='review'}
   }
   for(const t of state.teamParcels||[]){if(state.supportRequests.some(a=>a.legacyParcelId===t.id))continue;state.supportRequests.push({id:'AP-'+t.id,legacyParcelId:t.id,from:t.from,to:t.to,repairIds:t.items.map(i=>i.repairId),due:t.due,payment:t.payment,note:t.note,status:t.stage==='requested'?'pending':t.stage==='declined'?'declined':'accepted',createdAt:t.history?.[0]?.at||0})}
   state.workScopeVersion=1;
   try{localStorage.setItem('hilando-v1',JSON.stringify(state))}catch{}
 }
}
initWorkScope();
function holder(id){const r=state.repairs.find(r=>r.id===id);return r?.responsible||r?.receivedBy||'Rosa'}
function myRepairs(){return state.repairs.filter(r=>holder(r.id)===currentPerson)}
function workAgreement(r){return [...state.supportRequests].reverse().find(a=>a.status==='accepted'&&a.to===holder(r.id)&&a.repairIds.includes(r.id))}
function workDue(r){const a=workAgreement(r);return a?.due?teamDate(a.due):r.date}
function supportActive(id){return state.supportRequests.some(a=>a.repairIds.includes(id)&&a.status==='pending')}
function eligibleRepairs(){return myRepairs().filter(r=>['pending','working'].includes(r.stage)&&!supportActive(r.id))}
function personaChanged(name){if(![...teamPeople,'Dueña'].includes(name))return;currentPerson=name;repairFilter='pending';navigate(name==='Dueña'?'overview':'inicio')}
function personaControl(){return '<details class="persona-demo"><summary>Probar otra vista · Demostración</summary><p>Son perfiles de prueba en este navegador.</p><label>Estoy probando como<select id="demo-person" onchange="personaChanged(this.value)">'+[...teamPeople,'Dueña'].map(n=>'<option '+(n===currentPerson?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label></details>'}
function incomingBanner(){const n=state.supportRequests.filter(a=>a.to===currentPerson&&a.status==='pending').length;return n?'<button class="incoming-banner" onclick="navigate(\'team\')">'+icon('team')+' '+n+' solicitudes de apoyo por responder</button>':''}
function supportStatus(a){return {pending:'Esperando respuesta',accepted:'Apoyo aceptado',declined:'No aceptado',cancelled:'Cancelado'}[a.status]||'Por revisar'}
function supportCard(a){return '<section class="profile-sheet"><h3>'+esc(a.from)+' → '+esc(a.to)+'</h3><p>'+a.repairIds.map(id=>{const r=state.repairs.find(r=>r.id===id);return esc(r?r.garment+' · '+id:id)}).join('<br>')+'</p><p>'+esc(a.note)+'</p><p>Fecha: '+esc(teamDate(a.due))+'<br>Pago por el apoyo: '+repairMoney(a.payment)+'</p><strong>'+supportStatus(a)+'</strong>'+(a.status==='pending'&&a.to===currentPerson?'<div class="modalactions">'+button('Sí, puedo ayudar',"answerWorkSupport('"+a.id+"',true)",true,'check')+button('Ahora no puedo',"answerWorkSupport('"+a.id+"',false)")+'</div>':'')+(a.status==='pending'&&a.from===currentPerson?button('Cancelar solicitud',"cancelWorkSupport('"+a.id+"')"):'')+'</section>'}
function teamPage(){const rows=state.supportRequests.filter(a=>a.from===currentPerson||a.to===currentPerson);return '<div class="greeting"><p class="eyebrow">NOS ORGANIZAMOS JUNTAS</p><h1>Ayuda entre compañeras</h1><p class="sub">Elige quién puede ayudarte y acuerden la fecha y el pago.</p></div>'+button('Pedir ayuda a una compañera','composeSupport()',true,'team')+'<div class="parcel-list">'+rows.map(supportCard).join('')+(rows.length?'':'<div class="panel empty">Todavía no hay acuerdos de apoyo.</div>')+'</div>'}
function composeSupport(preselect){const rows=eligibleRepairs();if(!rows.length){modal('No hay arreglos disponibles','<p>Puedes pedir apoyo con trabajos pendientes o en curso que no tengan otra solicitud por responder.</p>');return}composeDraft={selected:preselect?[preselect]:[]};modal('¿Con qué necesitas apoyo?','<form id="pick-items"><div class="choose-items">'+rows.map(r=>'<label class="choose-row"><input name="repair" type="checkbox" value="'+r.id+'" '+(r.id===preselect?'checked':'')+'><span>'+esc(r.garment)+' · '+r.id+'</span></label>').join('')+'</div><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Continuar</button></div></form>');document.getElementById('pick-items').onsubmit=e=>{e.preventDefault();composeDraft.selected=[...document.querySelectorAll('input[name="repair"]:checked')].map(i=>i.value);if(!composeDraft.selected.length){toast('Elige al menos un arreglo.');return}composeDetails()}}
function composeDetails(){const people=teamPeople.filter(n=>n!==currentPerson);if(!people.length)return;modal('Pedir ayuda a una compañera','<form id="support-form"><label class="field">¿A qué compañera?<select id="support-to">'+people.map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><div class="colleague-summary" id="colleague-summary"></div><label class="field">¿Para qué día necesitas la ayuda?<input id="support-date" type="date" required></label><label class="field">¿Cuánto acordaron pagar? (S/)<input id="support-pay" type="number" min="0" step="0.01" required></label><label class="field">¿Qué necesitas que haga?<textarea id="support-note" maxlength="500" required></textarea></label><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Revisar acuerdo</button></div></form>');const target=document.getElementById('support-to');if(composeDraft.to)target.value=composeDraft.to;document.getElementById('support-date').value=composeDraft.due||'';document.getElementById('support-pay').value=composeDraft.payment??'';document.getElementById('support-note').value=composeDraft.note||'';const summary=()=>document.getElementById('colleague-summary').innerHTML=colleagueSummary(target.value);target.onchange=summary;summary();document.getElementById('support-form').onsubmit=e=>{e.preventDefault();const note=document.getElementById('support-note').value.trim(),payment=Number(document.getElementById('support-pay').value);if(!note||!Number.isFinite(payment)||payment<0)return;Object.assign(composeDraft,{to:target.value,due:document.getElementById('support-date').value,payment,note});reviewWorkSupport()}}
function reviewWorkSupport(){const d=composeDraft;modal('Revisar acuerdo','<p><strong>'+esc(currentPerson)+' → '+esc(d.to)+'</strong></p><p>'+d.selected.map(id=>{const r=state.repairs.find(r=>r.id===id);return esc(r.garment)+' · '+id}).join('<br>')+'</p><p>'+esc(d.note)+'</p><p>Fecha: '+esc(teamDate(d.due))+'<br>Pago por el apoyo: '+repairMoney(d.payment)+'</p><div class="modalactions">'+button('Volver a editar','composeDetails()')+button('Guardar solicitud','saveWorkSupport()',true)+'</div>')}
function saveWorkSupport(){const d=composeDraft;if(!d||!d.selected.length||!d.to||!teamPeople.includes(d.to)||d.to===currentPerson||!d.due||!d.note||!Number.isFinite(d.payment)||d.payment<0)return;if(d.selected.some(id=>!eligibleRepairs().some(r=>r.id===id))){toast('Algún arreglo ya cambió. Revisa tus trabajos.');return}state.supportRequests.push({id:'AP-'+Date.now().toString(36),from:currentPerson,to:d.to,repairIds:[...d.selected],due:d.due,payment:d.payment,note:d.note,status:'pending',createdAt:Date.now()});composeDraft=null;dialog.close();page='team';selectedRepair=null;save(currentPerson+' pidió apoyo a '+d.to+' con '+d.selected.join(', ')+'.');toast('Tu solicitud quedó guardada. '+d.to+' todavía debe responder.')}
function answerWorkSupport(id,accept){const a=state.supportRequests.find(a=>a.id===id);if(!a||a.to!==currentPerson||a.status!=='pending')return;const rows=a.repairIds.map(id=>state.repairs.find(r=>r.id===id));if(accept&&rows.some(r=>!r||holder(r.id)!==a.from||!['pending','working'].includes(r.stage))){toast('El trabajo cambió. Coordina un nuevo acuerdo.');return}a.status=accept?'accepted':'declined';a.answeredAt=Date.now();if(accept)for(const r of rows){r.responsible=a.to;r.stage='pending';r.supportId=a.id}save(currentPerson+(accept?' aceptó':' no pudo aceptar')+' el apoyo '+id+'.');toast(accept?'El arreglo aparece en tus trabajos.':'Respuesta guardada.')}
function cancelWorkSupport(id){const a=state.supportRequests.find(a=>a.id===id);if(!a||a.from!==currentPerson||a.status!=='pending')return;a.status='cancelled';save(currentPerson+' canceló la solicitud '+id+'.')}
function mediaDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('rapicostura-media',1);q.onupgradeneeded=()=>q.result.createObjectStore('files');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function mediaPut(id,file){const db=await mediaDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
render=function(){initWorkScope();if(currentPerson==='Dueña')return;main.innerHTML=(page==='team'?teamPage():page==='apoyo'?helpPage():selectedRepair?repairDetail():repairList())+personaControl();document.getElementById('mobile-nav').innerHTML=[['inicio','orders','Mis trabajos'],['team','team','Apoyos'],['apoyo','help','Ayuda']].map(([p,i,label])=>'<button class="'+(page===p?'active':'')+'" onclick="navigate(\''+p+'\')">'+icon(i)+'<span>'+label+'</span></button>').join('')};
